sd3(v) := dd(floor(1000*v+1/2)/1000);
ab(v, k) := if is(abs(v-floor(10^k*v+1/2)/10^k) < 10^(-9)) then "" else "about ";
xv: ans1*S/P;
xk: floor(100*xv+1/2)/100;

